import { requireAdmin } from "@/lib/auth"; import { verificationSchema } from "@/lib/admin-validations"; import { logAdminAction } from "@/lib/admin"; import { db } from "@/lib/db"; import { fail, handleApiError, ok } from "@/lib/http";
export async function POST(request: Request, { params }: { params: { id: string } }) { try { const actor = await requireAdmin(); const parsed = verificationSchema.safeParse(await request.json()); if (!parsed.success) return fail(parsed.error.issues[0]?.message || "Invalid level", 422); const current = await db.vendor.findUnique({ where: { id: params.id } }); if (!current) return fail("Vendor not found", 404); const vendor = await db.$transaction(async (tx) => { const updated = await tx.vendor.update({ where: { id: params.id }, data: { verificationLevel: parsed.data.level, verificationNotes: parsed.data.notes, isVerified: parsed.data.level > 0 } }); await logAdminAction(tx, { actorId: actor.id, action: "vendor_verification_changed", entityType: "vendor", entityId: params.id, reason: parsed.data.notes, metadata: { from: current.verificationLevel, to: parsed.data.level } }); return updated; }); return ok(vendor); } catch (error) { return handleApiError(error); } }
